/*
 * A042207  Denominators of continued fraction convergents to sqrt(629).
 * https://oeis.org/A042207
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 5, u32 n <= 12, u64 n <= 23, u128 n <= 45,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Recurrence: q[-1] = 0, q[0] = 1;  q[n] = a[n] * q[n-1] + q[n-2]
 * where a[n] are the partial quotients of the continued fraction of sqrt(629).
 * The partial quotients are generated by the standard algorithm:
 *   m_{k+1} = d_k * a_k - m_k
 *   d_{k+1} = (N - m_{k+1}^2) / d_k
 *   a_{k+1} = floor( (a0 + m_{k+1}) / d_{k+1} )
 * with N = 629 and a0 = floor(sqrt(629)) = 25. */

#include <stdint.h>   /* for uint64_t */

/* adjust the cache size as needed; 20001 covers n up to 10000 comfortably */
#define MAX_CACHE 20001

static seq_t cache[MAX_CACHE];
static idx_t cache_max = (idx_t)-1;   /* -1 means uninitialised */
static seq_t prev1 = 0, prev2 = 0;   /* q[n-1] and q[n-2] during extension */
static uint64_t m_val = 0, d_val = 1, a_val;  /* current m, d, a */

/* constants for sqrt(629) */
static const uint64_t N_CONST = 629ULL;
static const uint64_t A0_CONST = 25ULL;   /* floor(sqrt(629)) */

/* Extend the cache up to index n (inclusive) */
static void extend(idx_t n)
{
    if (cache_max == (idx_t)-1) {
        /* first use: initialise */
        cache[0]   = (seq_t)1;
        prev1      = (seq_t)1;   /* q[0] */
        prev2      = (seq_t)0;   /* q[-1] */
        m_val      = 0;
        d_val      = 1;
        a_val      = A0_CONST;
        cache_max  = 0;
    }
    if (n <= cache_max)
        return;

    for (idx_t i = cache_max + 1; i <= n; ++i) {
        /* next partial quotient */
        uint64_t m_next = d_val * a_val - m_val;
        uint64_t d_next = (N_CONST - m_next * m_next) / d_val;
        uint64_t a_next = (A0_CONST + m_next) / d_next;

        /* compute q[i] = a_next * q[i-1] + q[i-2] */
        seq_t q = prev1 * (seq_t)a_next + prev2;
        cache[i] = q;

        /* shift for next iteration */
        prev2 = prev1;
        prev1 = q;
        m_val = m_next;
        d_val = d_next;
        a_val = a_next;
    }
    cache_max = n;
}

/* public routine required by the framework */
seq_t a(idx_t n)
{
    /* if request is within the pre‑allocated cache, use it */
    if (n < (idx_t)MAX_CACHE) {
        extend(n);
        return cache[n];
    }

    /* otherwise compute the term without caching (single iteration) */
    uint64_t m_local = 0, d_local = 1, a_local = A0_CONST;
    seq_t q_prev2 = (seq_t)0, q_prev1 = (seq_t)1, q = (seq_t)1;   /* q[0] */

    if (n == 0)
        return q;

    for (idx_t i = 1; i <= n; ++i) {
        uint64_t m_next = d_local * a_local - m_local;
        uint64_t d_next = (N_CONST - m_next * m_next) / d_local;
        uint64_t a_next = (A0_CONST + m_next) / d_next;

        seq_t q_new = q_prev1 * (seq_t)a_next + q_prev2;
        q_prev2 = q_prev1;
        q_prev1 = q_new;
        q = q_new;

        m_local = m_next;
        d_local = d_next;
        a_local = a_next;
    }
    return q;
}
